// Why Code: transpose the key|value Settings tab into one object.
const rows = $input.all().map((i) => i.json);
const cfg = {};
for (const r of rows) {
  const k = String(r.key ?? '').trim();
  if (k) cfg[k] = r.value ?? '';
}
return [{ json: cfg }];

// Why Code: nested grouping + coverage math with formatted labels; no native node does this.
const cfg = $('Pivot Settings').first().json;
const facility = cfg.facilityName || 'the facility';
const tz = cfg.timezone || 'Africa/Lagos';
const now = DateTime.now().setZone(tz);
const today = now.startOf('day');
const horizon = today.plus({ days: 13 });
const rows = $('Read Rota').all().map((i) => i.json);
const upcoming = [];
const byShift = new Map();
for (const r of rows) {
  const d = DateTime.fromFormat(String(r.date), 'yyyy-MM-dd', { zone: tz });
  if (!d.isValid || d < today || d > horizon) continue;
  if (!byShift.has(r.shiftId)) {
    byShift.set(r.shiftId, { shiftId: r.shiftId, date: r.date, startTime: r.startTime, endTime: r.endTime,
      ward: r.ward, role: r.role, requiredCount: Number(r.requiredCount) || 1,
      confirmed: 0, pending: 0, declined: 0, staff: [] });
  }
  const g = byShift.get(r.shiftId);
  const st = String(r.status).toUpperCase();
  if (st === 'CONFIRMED') g.confirmed += 1; else if (st === 'DECLINED') g.declined += 1; else g.pending += 1;
  g.staff.push({ name: r.staffName, status: st, role: r.role });
}
let requiredSlots = 0, confirmedSlots = 0, pendingCount = 0, understaffedCount = 0;
for (const g of byShift.values()) {
  requiredSlots += g.requiredCount;
  confirmedSlots += Math.min(g.confirmed, g.requiredCount);
  pendingCount += g.pending;
  g.missingCount = Math.max(0, g.requiredCount - g.confirmed);
  g.understaffed = g.missingCount > 0;
  if (g.understaffed) understaffedCount += 1;
  const start = DateTime.fromFormat(String(g.date) + ' ' + String(g.startTime), 'yyyy-MM-dd HH:mm', { zone: tz });
  g.minutesUntilStart = start.isValid ? Math.round(start.diff(now, 'minutes').minutes) : null;
  g.atRisk = g.pending > 0 && g.minutesUntilStart !== null && g.minutesUntilStart <= 195 && g.minutesUntilStart >= -120;
  upcoming.push(g);
}
upcoming.sort((a, b) => (a.date + 'T' + a.startTime).localeCompare(b.date + 'T' + b.startTime));
const coverageRate = requiredSlots ? Math.round((confirmedSlots / requiredSlots) * 1000) / 10 : 100;
const atRisk = upcoming.filter((g) => g.atRisk);
return [{ json: { response: {
  facility, generatedAt: now.toISO(), timezone: tz, windowDays: 14,
  stats: {
    shifts: byShift.size, requiredSlots, confirmedSlots, coverageRate,
    pendingConfirmations: pendingCount, understaffedShifts: understaffedCount,
    atRiskShifts: atRisk.length,
  },
  upcoming,
  atRisk,
} } }];
